class DecryptionUtils:
    ALPHABET_SIZE = 26
    ASCII_UPPER_A = 65
    ASCII_LOWER_A = 97

    def __init__(self, key):
        self._key = key

    @property
    def key(self):
        return self._key

    @key.setter
    def key(self, value):
        self._key = value

    def caesar_decipher(self, ciphertext, shift):
        plaintext = ""
        for char in ciphertext:
            if char.isalpha():
                shifted_char = self._shift_char(char, shift)
                plaintext += shifted_char
            else:
                plaintext += char
        return plaintext

    def _shift_char(self, char, shift):
        if char.isupper():
            ascii_offset = self.ASCII_UPPER_A
        else:
            ascii_offset = self.ASCII_LOWER_A
        return chr((ord(char) - ascii_offset - shift) % self.ALPHABET_SIZE + ascii_offset)

    def vigenere_decipher(self, ciphertext):
        decrypted_text = ""
        key_index = 0
        for char in ciphertext:
            if char.isalpha():
                shift = self._get_key_shift(key_index)
                base_char = char.lower()
                decrypted_char = chr((ord(base_char) - self.ASCII_LOWER_A - shift) % self.ALPHABET_SIZE + self.ASCII_LOWER_A)
                if char.isupper():
                    decrypted_char = decrypted_char.upper()
                decrypted_text += decrypted_char
                key_index += 1
            else:
                decrypted_text += char
        return decrypted_text

    def _get_key_shift(self, key_index):
        key_char = self._key[key_index % len(self._key)].lower()
        return ord(key_char) - self.ASCII_LOWER_A

    def rail_fence_decipher(self, encrypted_text, rails):
        fence_pattern = self._build_fence_pattern(len(encrypted_text), rails)
        fence = self._fill_fence(fence_pattern, encrypted_text)
        plain_text = self._read_fence(fence, len(encrypted_text), rails)
        return plain_text

    def _build_fence_pattern(self, length, rails):
        fence = [['\n' for _ in range(length)] for _ in range(rails)]
        direction = -1
        row, col = 0, 0

        for _ in range(length):
            if row == 0 or row == rails - 1:
                direction = -direction

            fence[row][col] = ''
            col += 1
            row += direction

        return fence

    def _fill_fence(self, fence, encrypted_text):
        index = 0
        for i in range(len(fence)):
            for j in range(len(fence[0])):
                if fence[i][j] == '':
                    fence[i][j] = encrypted_text[index]
                    index += 1
        return fence

    def _read_fence(self, fence, length, rails):
        plain_text = ''
        direction = -1
        row, col = 0, 0
        for _ in range(length):
            if row == 0 or row == rails - 1:
                direction = -direction

            plain_text += fence[row][col]
            col += 1
            row += direction

        return plain_text
